import{z as i,x as s,o as A,c as o,q as e,j as r,D as a,d as l,s as t,S as n}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"分布式训练的调试","description":"","frontmatter":{"title":"分布式训练的调试","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dist-debugging.md","filePath":"llm/dist-debugging.md","lastUpdated":1791413859000}'),d={name:"llm/dist-debugging.md"};function D(C,E,p,h,F,m){const B=s("Mermaid");return A(),o("div",null,[E[2]||(E[2]=e('<h1 id="分布式训练的调试" tabindex="-1">分布式训练的调试 <a class="header-anchor" href="#分布式训练的调试" aria-label="Permalink to &quot;分布式训练的调试&quot;">​</a></h1><div class="epigraph"><p>分布式 bug 的难点不在多机，在于你只有全局状态的一万份残影；调试就是把残影拼回时间线。</p><footer>—— 据 NCCL 调试口径与 PyTorch 分布式工具链整理</footer></div><p><a href="/llm/dist-memory-budget">上一课</a>的清单拦住配置错误；跑起来之后的三类病——挂起、loss 异常、吞吐骤降——各有各的定位法。本课写分布式训练的调试：症状到二分到工具，以及为什么单卡直觉在多卡上系统性失效。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三类症状经常互相伪装。挂起的表象是 NCCL 超时，根因可能是某 rank 崩了、某条链路降速、或某 rank 走了一条别人没走的代码分支；loss 毛刺与发散的来源有三处——数据、数值、并行配置——表象却都是曲线难看；吞吐骤降可能是故障链路的前奏，也可能只是落后者。单卡直觉失效的根因：错误是跨进程的时序现象，你手里的栈回溯只是一个 rank 的残影；重跑常常不可复现，因为时序本身参与因果。</p><h3 id="三分法" tabindex="-1">三分法 <a class="header-anchor" href="#三分法" aria-label="Permalink to &quot;三分法&quot;">​</a></h3><p>挂起先分「全组同挂」还是「个别 rank 迟到」：全组同挂看最先报超时的域，个别迟到抓全组栈对比——每个 rank 停在哪一行，一对比就现形。头号根因是集体调用不对称：某 rank 因数据条件分支多调或少调了一次集合通信，其余全体等它。loss 异常按三处归因：数据处查分片内容与顺序（可复现性靠数据内排序键，口径见<a href="/llm/distributed-clean">分布式清洗</a>）；数值处看梯度范数序列与异常值统计，并回单卡复现同一段数据；并行配置处查分片下标、全局范数归约是否漏做、RNG 是否各 rank 一致。吞吐骤降先过容错课的检测链路排除半坏状态，再走 MFU 课的分解。</p><p><span class="marginnote">对拍协议是分布式调试的主力工具：缩小模型、降到 2 到 8 卡、关 overlap、关卸载，四步各做一次，看异常何时消失——消失的那一步就是嫌疑域。大多数跨卡问题在小规模上保持复现，不用回千卡验证假设。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>调试的固定动作序：第一步固定输入（同分片、同顺序、同种子），把「变量」压到只剩并行结构；第二步降规模复现，用对拍协议找嫌疑域；第三步在嫌疑域内上工具——挂起用调试级日志加全组栈采样，数值用逐层范数与逐张量校验和对照，通信用带宽曲线对照第 4 课的时序计划；第四步把根因写进固定字段（症状、嫌疑域、复现配置、修复、回归测试），进实验台账。工具的版本差异大，记方法不记逐版本命令：栈采样、分域超时、内存快照、通信 trace 四件套的语义各框架通用。</p><p><span class="marginnote">固定输入这一步的价值常被低估：多卡上各 rank 的数据分片顺序、dropout 的随机种子都可能不一样——不先把这些钉死，你对比的两个实验根本不是同一个实验，看出的「差异」只是噪声。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么集体通信把局部错误放大成全局挂起：集合通信是全组合同，任一成员不到场，其余全体阻塞在栅栏——这决定了挂起调试的第一动作永远是「找最先异常的那一个 rank」，而不是看超时报告的第一行。为什么数值 bug 要回单卡复现：并行的数值差异主要来自归约顺序与分片切法，单卡跑同一段数据能把「数值本身的病」与「并行引入的病」分开；两者都病，先治单卡。为什么确定性重放有上限：数据与种子可复现，时钟与网络不可复现，所以调试协议追求「复现到嫌疑域」而不是「逐比特重放」。</p><p><span class="marginnote">集合通信（collective）就是全组一起参加的通信操作，少了谁都不行；栅栏可以想象成考场的进场铃——所有人到齐门才开，一个人没来，全考场都堵在门口。这就是「一个 rank 多调一次归约、全体陪它挂起」的原因。</span></p>',14)),(A(),r(n,null,{default:a(()=>[t(B,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20R0%5B%22rank%200%3A%20%E5%BD%92%E7%BA%A6%201%20%E2%86%92%20%E5%BD%92%E7%BA%A6%202%20%E2%86%92%20%E5%BD%92%E7%BA%A6%203%22%5D%20--%3E%20BLK%5B%22%E5%85%B6%E4%BD%99%20rank%20%E5%81%9C%E5%9C%A8%E7%AC%AC%202%20%E6%AC%A1%E5%BD%92%E7%BA%A6%E7%9A%84%E6%A0%85%E6%A0%8F%E4%B8%8A%E5%B9%B2%E7%AD%89%22%5D%0A%20%20R1%5B%22rank%201%3A%20%E5%BD%92%E7%BA%A6%201%20%E2%86%92%20%E5%BD%92%E7%BA%A6%202%20(%E8%B5%B0%E4%BA%86%E5%A4%9A%E4%B8%80%E6%AD%A5%E7%9A%84%E5%88%86%E6%94%AF)%22%5D%20--%3E%20BLK%0A%20%20R2%5B%22rank%202%3A%20%E5%BD%92%E7%BA%A6%201%20%E2%86%92%20%E5%BD%92%E7%BA%A6%202%22%5D%20--%3E%20BLK%0A%20%20BLK%20--%3E%20TO%5B%22%E8%B6%85%E6%97%B6%E4%BB%8E%E6%9C%80%E5%85%88%E5%88%B0%E6%9C%9F%E7%9A%84%E5%9F%9F%E5%86%92%E5%87%BA%E6%9D%A5%22%5D%0A%20%20TO%20--%3E%20CMP%5B%22%E6%8A%93%E5%85%A8%E7%BB%84%E6%A0%88%3A%20%E6%AF%8F%E4%B8%AA%20rank%20%E5%81%9C%E5%9C%A8%E5%93%AA%E4%B8%80%E8%A1%8C%2C%20%E4%B8%80%E5%AF%B9%E6%AF%94%E5%B0%B1%E7%8E%B0%E5%BD%A2%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),(A(),r(n,null,{default:a(()=>[t(B,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYM%7B%22%E7%97%87%E7%8A%B6%3F%22%7D%20--%3E%20HANG%5B%22%E6%8C%82%E8%B5%B7%3A%20NCCL%20%E8%B6%85%E6%97%B6%22%5D%0A%20%20SYM%20--%3E%20LOSS%5B%22loss%20%E6%AF%9B%E5%88%BA%E6%88%96%E5%8F%91%E6%95%A3%22%5D%0A%20%20SYM%20--%3E%20PERF%5B%22%E5%90%9E%E5%90%90%E9%AA%A4%E9%99%8D%22%5D%0A%20%20HANG%20--%3E%20W%7B%22%E5%85%A8%E7%BB%84%E5%90%8C%E6%8C%82%20%E6%88%96%20%E4%B8%AA%E5%88%AB%E8%BF%9F%E5%88%B0%3F%22%7D%0A%20%20W%20--%3E%7C%E4%B8%AA%E5%88%AB%E8%BF%9F%E5%88%B0%7C%20STACK%5B%22%E6%8A%93%E5%85%A8%E7%BB%84%E6%A0%88%E5%AF%B9%E6%AF%94%2C%20%E6%89%BE%E6%9C%80%E5%85%88%E5%BC%82%E5%B8%B8%20rank%22%5D%0A%20%20W%20--%3E%7C%E5%85%A8%E7%BB%84%E5%90%8C%E6%8C%82%7C%20DOM%5B%22%E7%9C%8B%E6%9C%80%E5%85%88%E6%8A%A5%E8%B6%85%E6%97%B6%E7%9A%84%E5%9F%9F%3A%20%E5%8D%A1%20%2F%20%E9%93%BE%E8%B7%AF%20%2F%20%E4%B8%BB%E6%9C%BA%22%5D%0A%20%20LOSS%20--%3E%20TRI%7B%22%E6%95%B0%E6%8D%AE%20%2F%20%E6%95%B0%E5%80%BC%20%2F%20%E5%B9%B6%E8%A1%8C%3F%22%7D%0A%20%20TRI%20--%3E%20FIXIN%5B%22%E5%9B%BA%E5%AE%9A%E8%BE%93%E5%85%A5%E4%B8%8E%E7%A7%8D%E5%AD%90%2C%20%E5%9B%9E%E5%8D%95%E5%8D%A1%E5%A4%8D%E7%8E%B0%22%5D%0A%20%20TRI%20--%3E%20PARA%5B%22%E6%9F%A5%E5%88%86%E7%89%87%E4%B8%8B%E6%A0%87%E4%B8%8E%E5%85%A8%E5%B1%80%E8%8C%83%E6%95%B0%E5%BD%92%E7%BA%A6%22%5D%0A%20%20PERF%20--%3E%20FAULT%5B%22%E5%85%88%E6%8E%92%E9%99%A4%E5%8D%8A%E5%9D%8F%E7%8A%B6%E6%80%81%2C%20%E5%86%8D%E8%B5%B0%20MFU%20%E5%88%86%E8%A7%A3%22%5D%0A%20%20STACK%20--%3E%20BISECT%5B%22%E5%AF%B9%E6%8B%8D%E5%9B%9B%E6%AD%A5%3A%20%E7%BC%A9%E6%A8%A1%E5%9E%8B%20%2F%20%E9%99%8D%E5%8D%A1%20%2F%20%E5%85%B3%E9%87%8D%E5%8F%A0%20%2F%20%E5%85%B3%E5%8D%B8%E8%BD%BD%22%5D%0A%20%20DOM%20--%3E%20BISECT%0A%20%20FIXIN%20--%3E%20BISECT%0A%20%20PARA%20--%3E%20BISECT%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>单卡数值调试与异常值机理归数值课程；故障的检测与退役归容错课，本课只接「已挂起之后」的定位；性能类问题归 MFU 与建模课。调试不等于监控：生产上的指标与告警让故障被看见，调试让根因被找到，两者共用台账但不是一套东西。最后一条纪律：调试结论没有回归测试兜底就不算关闭——集合通信的不对称 bug 修完不补一个「分支不对称即报错」的断言，下次换个人照样踩。</p><p><span class="marginnote">「根因写进固定字段」听起来像官僚流程，在分布式里其实是刚需：时序类 bug 常常几周后换个集群又复发，台账里的复现配置与回归断言，是那时唯一能让你十分钟收工而不是重新查三天的东西。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三类症状互相伪装，先分类再动手：挂起找最先异常的 rank，loss 走数据/数值/并行三分，吞吐先排故障再走分解。</li><li>集体通信是全组合同，局部错误放大成全局挂起；调试第一动作是找最先异常者。</li><li>对拍四步（缩模型、降卡、关重叠、关卸载）是主力工具，多数问题在小规模复现。</li><li>数值 bug 回单卡复现，把数值病与并行病分开治；确定性重放只到嫌疑域为止。</li><li>出处：NCCL 调试口径；PyTorch 分布式工具链；可复现数据口径见<a href="/llm/distributed-clean">分布式清洗</a>。</li></ul>',5))])}const T=i(d,[["render",D]]);export{u as __pageData,T as default};
